export function varExists(t,e){return"__failedToFind__"!=objectValFromStringPos(t,e,"__failedToFind__")}export function varGet(t,e,r=""){return objectValFromStringPos(t,e,r)}export function objectValFromStringPos(t,e,r=null){let n=(e=(e=e.replace(/\[(\w+)\]/g,".$1")).replace(/^\./,"")).split(".");for(let e=0,o=n.length;e<o;++e){let o=n[e];if(!t)return r;if(!(o in t))return r;t=t[o]}return t}export function valueMapTransform(t,e){let r=[];return e&&t.forEach(t=>{let n={};for(let r in e){let o=e[r];if(!0===o||!1===o||null===o)n[r]=o;else if("function"==typeof o)try{n[r]=o(t)}catch(t){console.warn(t)}else"string"==typeof o&&varExists(t,o)?n[r]=varGet(t,o):n[r]=o}r.push(n)}),r}